<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="csrf-token" content="{{ csrf_token() }}"><title>eBay ended listing cleanup runner</title><style>body{font-family:system-ui,sans-serif;margin:24px}.panel{border:1px solid #ddd;padding:16px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px}.card{background:#f9fafb;border:1px solid #e5e7eb;padding:10px}.card strong{display:block;font-size:1.3rem}pre{background:#f3f4f6;padding:12px;overflow:auto}button{margin:4px;padding:8px 12px}.exports a{display:inline-block;margin:4px 8px 4px 0}.ok{color:#166534}.error{color:#991b1b}</style></head><body>
