<script>(()=>{const statusUrl=@json(route('admin.tools.ebay.listing-status-audit-runner.status',['json'=>1]));const runUrl=@json(route('admin.tools.ebay.listing-status-audit-runner.run-next-batch'));const csrf=document.querySelector('meta[name="csrf-token"]').content;const keys=['status','mode','total_candidates_at_start','processed','remaining','active_count','ended_count','not_found_count','skipped_count','failed_count','cleanup_recommended_count','cleaned_count'];function render(s){document.getElementById('failedSkippedExports').style.display=((Number(s?.failed_count||0)+Number(s?.skipped_count||0))>0)?'inline':'none';document.getElementById('grid').innerHTML=keys.map(k=>`<div class="card"><span>${k}</span><strong>${s?.[k]??'—'}</strong></div>`).join('');document.getElementById('results').textContent=JSON.stringify(s,null,2)}async function get(){const r=await fetch(statusUrl,{headers:{Accept:'application/json'}});const j=await r.json();render(j);return j}async function next(){const r=await fetch(runUrl,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:'{}'});return r.json()}async function loop(){const s=await get();if(s.status==='running'&&s.remaining>0){setTimeout(async()=>{await next();loop()},Math.max(0,Number(s.retry_after_seconds||s.delay_seconds||2))*1000)}}document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',()=>setTimeout(loop,1000)));loop();})();</script>
